('Leg Press (Machine)', 'Upper Legs', array['Glutes']::text[], 'Strength Machine', 'weight_reps', 'Feet shoulder-width on the platform, lower the sled until knees near 90 degrees, then press without locking out.'),
('Leg Extension (Machine)', 'Upper Legs', '{}'::text[], 'Strength Machine', 'weight_reps', 'Seated with the pad above your ankles, extend your knees to straight, pause, and lower slowly — no swinging.'),
('Lying Leg Curl (Machine)', 'Upper Legs', '{}'::text[], 'Strength Machine', 'weight_reps', 'Face down with the pad above your heels, curl your legs toward your glutes and lower with control.'),
('Seated Leg Curl (Machine)', 'Upper Legs', '{}'::text[], 'Strength Machine', 'weight_reps', 'Seated with legs extended, curl the pad down and under, squeezing your hamstrings, then return slowly.'),
('Romanian Deadlift (Barbell)', 'Upper Legs', array['Glutes','Back']::text[], 'Barbell', 'weight_reps', 'From standing, push your hips back with soft knees, sliding the bar down your thighs until you feel a hamstring stretch, then stand.'),
('Romanian Deadlift (Dumbbell)', 'Upper Legs', array['Glutes','Back']::text[], 'Dumbbell', 'weight_reps', 'Hinge at the hips with flat back and soft knees, lowering the dumbbells along your legs, then drive hips forward to stand.'),
('Stiff-Leg Deadlift (Barbell)', 'Upper Legs', array['Glutes','Back']::text[], 'Barbell', 'weight_reps', 'With nearly straight knees, hinge until your hamstrings reach a deep stretch, then extend your hips to stand tall.'),
('Walking Lunge (Dumbbell)', 'Upper Legs', array['Glutes']::text[], 'Dumbbell', 'weight_reps', 'Step forward into a lunge until both knees hit 90 degrees, then drive through the front heel into the next step.'),
('Lunge (Barbell)', 'Upper Legs', array['Glutes']::text[], 'Barbell', 'weight_reps', 'With the bar on your back, step forward into a deep lunge and push back to standing; alternate legs.'),
('Reverse Lunge', 'Upper Legs', array['Glutes']::text[], 'Body Weight', 'bodyweight_reps', 'Step backward into a lunge, keeping your front shin vertical, then return to standing.'),
('Bulgarian Split Squat (Dumbbell)', 'Upper Legs', array['Glutes']::text[], 'Dumbbell', 'weight_reps', 'Rear foot elevated on a bench, lower straight down until your front thigh is parallel, then drive up through the front foot.'),
('Step-Up (Dumbbell)', 'Upper Legs', array['Glutes']::text[], 'Dumbbell', 'weight_reps', 'Holding dumbbells, step onto a knee-height bench driving through the top leg, then lower under control.'),
('Bodyweight Squat', 'Upper Legs', array['Glutes']::text[], 'Body Weight', 'bodyweight_reps', 'Squat to at least parallel with arms extended forward for balance, keeping heels down.'),
('Jump Squat', 'Upper Legs', array['Glutes','Cardio']::text[], 'Body Weight', 'bodyweight_reps', 'Squat to parallel and explode upward into a jump, landing softly straight into the next rep.'),
('Wall Sit', 'Upper Legs', '{}'::text[], 'Body Weight', 'duration', 'Slide down a wall until your thighs are parallel and hold the position with shins vertical.'),
('Pistol Squat', 'Upper Legs', array['Glutes','Abs']::text[], 'Body Weight', 'bodyweight_reps', 'Squat on one leg with the other extended forward, descending as low as possible before standing back up.'),
('Nordic Hamstring Curl', 'Upper Legs', '{}'::text[], 'Body Weight', 'bodyweight_reps', 'With ankles anchored, lower your torso forward from your knees as slowly as possible, catching yourself with your hands.'),
('Hip Adduction (Machine)', 'Upper Legs', '{}'::text[], 'Strength Machine', 'weight_reps', 'Seated with legs apart against the pads, squeeze your knees together and return slowly.'),
('Box Squat (Barbell)', 'Upper Legs', array['Glutes']::text[], 'Barbell', 'weight_reps', 'Squat back to a box, pause briefly without relaxing, then drive up explosively.'),
('Zercher Squat (Barbell)', 'Upper Legs', array['Glutes','Abs']::text[], 'Barbell', 'weight_reps', 'Cradle the bar in your elbow creases and squat deep, staying upright against the front load.'),
('Sissy Squat', 'Upper Legs', '{}'::text[], 'Body Weight', 'bodyweight_reps', 'Holding support, rise on your toes and lean your torso back while bending knees forward, then return upright.'),
('Wall Squat (Exercise Ball)', 'Upper Legs', array['Glutes']::text[], 'Exercise Ball', 'bodyweight_reps', 'With the ball between your lower back and a wall, squat until thighs are parallel and roll back up.'),
('Trap Bar Deadlift', 'Upper Legs', array['Glutes','Back']::text[], 'Barbell', 'weight_reps', 'Standing inside the hex bar, grip the handles, brace, and stand tall by driving through the floor.'),
('Standing Calf Raise (Machine)', 'Lower Legs', '{}'::text[], 'Strength Machine', 'weight_reps', 'Shoulders under the pads, balls of feet on the platform, rise as high as possible, pause, and lower into a deep stretch.'),
('Seated Calf Raise (Machine)', 'Lower Legs', '{}'::text[], 'Strength Machine', 'weight_reps', 'With the pad on your knees, raise your heels to full height and lower slowly to a stretch to hit the soleus.'),
('Calf Raise (Barbell)', 'Lower Legs', '{}'::text[], 'Barbell', 'weight_reps', 'With the bar on your back and toes on a small ledge, perform slow full-range heel raises.'),
('Calf Raise (Dumbbell)', 'Lower Legs', '{}'::text[], 'Dumbbell', 'weight_reps', 'Holding dumbbells at your sides, rise onto the balls of your feet, pause, and lower with control.'),
('Single-Leg Calf Raise', 'Lower Legs', '{}'::text[], 'Body Weight', 'bodyweight_reps', 'On one foot with toes on a step, perform full-range calf raises, using a wall for balance only.'),
('Calf Press (Leg Press Machine)', 'Lower Legs', '{}'::text[], 'Strength Machine', 'weight_reps', 'On the leg press with only your toes on the platform, press through the balls of your feet without moving your knees.'),
('Donkey Calf Raise', 'Lower Legs', '{}'::text[], 'Body Weight', 'bodyweight_reps', 'Hinged forward with your hands supported, drive up onto your toes for a stretched-position calf raise.'),
('Tibialis Raise', 'Lower Legs', '{}'::text[], 'Body Weight', 'bodyweight_reps', 'Leaning back against a wall with straight legs, lift your toes toward your shins as high as possible.'),
('Running (Outdoor)', 'Cardio', array['Upper Legs','Lower Legs']::text[], 'Body Weight', 'distance_duration', 'Run at a steady conversational pace or in intervals; log distance and duration.'),
('Treadmill Run', 'Cardio', array['Upper Legs']::text[], 'Cardio Machine', 'distance_duration', 'Run on the treadmill at your target pace or incline; log distance and duration.'),
('Walking', 'Cardio', array['Upper Legs']::text[], 'Body Weight', 'distance_duration', 'Brisk continuous walking, outdoors or on a treadmill; log distance and duration.'),
('Cycling (Stationary Bike)', 'Cardio', array['Upper Legs']::text[], 'Cardio Machine', 'distance_duration', 'Pedal at a steady cadence or in intervals with moderate resistance; log distance and duration.'),
('Rowing Machine', 'Cardio', array['Back','Upper Legs']::text[], 'Cardio Machine', 'distance_duration', 'Drive with legs, then swing your torso and pull the handle to your ribs; reverse the sequence on the return.'),
('Elliptical Trainer', 'Cardio', array['Upper Legs']::text[], 'Cardio Machine', 'distance_duration', 'Maintain a smooth stride using both handles and pedals; log duration and distance.'),
('Stair Climber', 'Cardio', array['Glutes','Upper Legs']::text[], 'Cardio Machine', 'distance_duration', 'Climb at a steady pace with a tall posture, using the rails only for balance.'),
('Jump Rope', 'Cardio', array['Lower Legs']::text[], 'Body Weight', 'duration', 'Skip with small, quick bounces on the balls of your feet, wrists doing the turning.'),
('Burpee', 'Cardio', array['Chest','Upper Legs']::text[], 'Body Weight', 'bodyweight_reps', 'Squat, kick back to a push-up, return your feet under you, and jump up — one fluid rep.'),
('Jumping Jack', 'Cardio', '{}'::text[], 'Body Weight', 'bodyweight_reps', 'Jump your feet out while raising your arms overhead, then return; keep a springy rhythm.'),
('High Knees', 'Cardio', array['Abs']::text[], 'Body Weight', 'duration', 'Run in place driving your knees to hip height at a fast cadence.'),
('Assault Bike', 'Cardio', array['Upper Legs','Shoulders']::text[], 'Cardio Machine', 'distance_duration', 'Drive the pedals and handles together at high effort, in intervals or steady state.')
