create table if not exists public.exercises (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  muscle_group text not null,
  secondary_muscles text[] not null default '{}',
  equipment text not null,
  exercise_type text not null default 'weight_reps',
  instructions text,
  is_custom boolean not null default false,
  created_by uuid references auth.users(id),
  created_at timestamptz not null default now()
);

alter table public.exercises enable row level security;

drop policy if exists "exercises_read_all" on public.exercises;
create policy "exercises_read_all" on public.exercises for select using (true);

drop policy if exists "exercises_insert_own" on public.exercises;
create policy "exercises_insert_own" on public.exercises for insert with check (auth.uid() = created_by and is_custom = true);

grant select, insert on public.exercises to authenticated;
grant select on public.exercises to anon;
grant all on public.exercises to service_role;

on conflict (name) do nothing;